import React, { useEffect, useState } from 'react';

import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import ListItemText from '@mui/material/ListItemText';

import { AccordionDetails, AccordionSummary, Box, Button, Step, StepLabel, Stepper, Tooltip } from '@mui/material';
import Accordion from '@mui/material/Accordion';
import YoutubeIcon from '@mui/icons-material/YouTube';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

import { CustomTypography } from '../materials/Typography';

export default function Contact() {

  const items= [
    {
      title: "Batched Support",
      description: "Youtube Demonstrations",
      channel: "Batched Support",
      src: [
        "https://www.youtube.com/embed/IJFOHNK-sBY?si=PXlTKlbJS7qaHsPR",
        "https://www.youtube.com/embed/eX7XDNOrv90?si=qR4uxR5TTRUHuZ-B",
        "https://www.youtube.com/embed/lQwYJoPhWwQ?si=WmTaPeI0Ib-7s82c",
      ],
      steps: [
        'Pickup a catered product from strathcona mrkt', 
        'How to subscribe to mrktbox', 
        'Sign Up To MRKTBOX'
      ],
      stepsLabels: [
        (  
          <>
            <CustomTypography variant="caption" component="span" sx={{ whiteSpace: 'pre-wrap' }}>
              {
                "Hi there, Aidan from MRKTBox."+
                "\n\nGiving you a quick tutorial on how to schedule a catered pickup"+
                " order from Strathcona MRKT."+
                "\n\n Click the market box drop down and select [a] service Channel."+
                " We're going to choose 'Catering'."+
                "\n Next, click the button for Strathcona MRKT and now we're going to schedule our order."+ 
                "\n Maybe we'll choose for August 23rd."+
                "\n\n Great, and now click the category for platters and choose your selected catering"+ 
                " item.\n I'm going to choose Chartcuterie platter."+
                "\n\n Now when we click in the top right corner we'll be able to see our order"+
                "and then we'll just need to sign in real quick."+
                "\n Once we've signed in we'll see that the order was requested."+
                "\n\n When we check our orders we'll be able to see our catering order details."+
                "\n\n...And if this video didn't answer your question there's"+
                " plenty of other videos to assist you."
              }
            </CustomTypography>
          </>
        ),
        (  
          <>
            <CustomTypography variant="caption" component="span" sx={{ whiteSpace: 'pre-wrap' }}>
              {"Hi there, Aidan from MRKTBox.\n\nGiving you a quick tutorial on how to subscribe to our MRKTBox"+
            " box delivery / pickup program.\n\n First make your MRKTBox selections and then add the MRKTBox"+
            " to your order.\n\n Click in the top right to see your order and then choose your service"+
            " channel type.\n\n Choose Grocery and then here we're choosing pickup for Dundurn MRKT.\n\n Now, we're"+
            " just going to choose Friday as a delivery day, go back to our order make sure to sign in "+
            "\n and then now we should have the option to subscribe and we'll just choose every 2 weeks\n\n"+
            "...And if this video didn't answer your question there's"+
            " plenty of others to assist you"}
            </CustomTypography>
          </>
        ),
        (
          <>
            <CustomTypography variant="caption" component="span" sx={{ whiteSpace: 'pre-wrap' }}>
              {
                "Hi there. Aidan from MRKTBox.\n\nGiving you a quick tutorial on how to sign up to our MRKTBox website.\n\n The first step is to click the hamburger icon in the top right corner of the screen.\n\n Click"+
                " on the button that reads sign up input your profile details ensuring your passwords are identical\n and make sure to read our terms of service and privacy"+
                " policy if you agree to our terms click the check box\n at the very bottom and when ready click the button that reads register.\n\n Congratulations! When"+
                " you navigate to your profile and view your details you'll know you're signed in\n\n...And if this video didn't answer your question there's plenty of others to assist you."}
            </CustomTypography>
          </>
        ),
      ],
    },
    {
      title: "Mohawk College",
      description: "TeaBank Capstone Final Demonstration",
      channel: "aidanOdyssey",
      src: [
        "https://www.youtube.com/embed/fVJ_0QYCSoI?si=p7jX3Wn7ylXdaZxE",
        "https://www.youtube.com/embed/1SbgMCq4-PM?si=yABv-EKPftpFo7fv",
        "https://www.youtube.com/embed/aFiUmvcF3Xw?si=R-781N2WEAGsqnZF",
      ],
      steps: ['Capstone Report 3', 'Capstone Report 4', 'Capstone Final Report'],
      stepsLabels: [
        (
          <CustomTypography component="span">
            {"This is the final demonstration of our TeaBank capstone project. In this video, we will be showcasing the final product and its features. We will also be discussing the development process and the challenges we faced along the way. We hope you enjoy the demonstration and find it informative."}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
      ],
    }, 
    {
      title: "Mohawk College",
      description: "PHP Demonstrations",
      channel: "aidanOdyssey",
      src: ["https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdWh_b2x-6Am0r08BeYy0H2g"],
      steps: ['Step 1', 'Step 2', 'Step 3'],
      stepsLabels: [
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
      ],
    },
    {
      title: "Mohawk College",
      description: "Mohawk College Technical Presentations",
      channel: "aidanOdyssey",
      src: ["https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdUla07BUe_gP5kNb0sowuh_"],
      steps: ['Step 1', 'Step 2', 'Step 3'],
      stepsLabels: [
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
        (
          <CustomTypography component="span">
            {"Test"}
          </CustomTypography>
        ),
      ],
    },
  ];

  const youtubeWidth = window.innerWidth > 600 ? "50%" : "100%";
  const youtubeHeight = window.innerWidth > 600 ? "50vh" : "30vh";
  
  const [elapsedTimes, setElapsedTimes] = useState<number[]>(items.map(() => 0));

  const [activeSteps, setActiveSteps] = useState<number[]>(items.map(() => 0));
  const [skippedSteps, setSkippedSteps] = useState<Set<number>[]>(items.map(() => new Set()));
  
  const isStepOptional = (step: number) => {
    return step === 1;
  };

  const isStepSkipped = (itemIndex: number, step: number) => {
    return skippedSteps[itemIndex]?.has(step);
  };

  const handleNext = (itemIndex: number) => {
    setActiveSteps((prev) => {
      const newSteps = [...prev];
      newSteps[itemIndex]++;
      return newSteps;
    });

    setElapsedTimes((prev) => {
    const newTimes = [...prev];
    newTimes[itemIndex] = 0;
    return newTimes;
  });
  };

  const handleBack = (itemIndex: number) => {
    setActiveSteps((prev) => {
      const newSteps = [...prev];
      newSteps[itemIndex]--;
      return newSteps;
    });

    setElapsedTimes((prev) => {
      const newTimes = [...prev];
      newTimes[itemIndex] = 0;
      return newTimes;
  });
  };

  const handleSkip = (itemIndex: number) => {
    if (!isStepOptional(activeSteps[itemIndex])) {
      throw new Error("You can't skip a step that isn't optional.");
    }

    setActiveSteps((prev) => {
      const newSteps = [...prev];
      newSteps[itemIndex]++;
      return newSteps;
    });

    setElapsedTimes((prev) => {
      const newTimes = [...prev];
      newTimes[itemIndex] = 0;
      return newTimes;
    });

    setSkippedSteps((prev) => {
      const newSkipped = [...prev];
      const newSet = new Set(newSkipped[itemIndex]);
      newSet.add(activeSteps[itemIndex]);
      newSkipped[itemIndex] = newSet;
      return newSkipped;
    });
  };

  const handleReset = (itemIndex: number) => {
    setActiveSteps((prev) => {
      const newSteps = [...prev];
      newSteps[itemIndex] = 0;
      return newSteps;
    });

    setElapsedTimes((prev) => {
      const newTimes = [...prev];
      newTimes[itemIndex] = 0;
      return newTimes;
    });
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setElapsedTimes((prev) =>
        prev.map((time) => time + 0.01)
      );
    }, 10);

    return () => clearInterval(interval);
  }, [items.length]);

  return (
      <>
      <List dense={false}>
      {items.map((item, index) => {
        const currentStep = activeSteps[index];
        const isCompleted = currentStep === item.steps.length;
        const elapsedTime = elapsedTimes[index];
        const progressPercent = Math.min((elapsedTime / 0.45) * 100, 100);
        return (
          <ListItem
            key={index}
            sx={{
              backgroundColor: index % 2 === 0 ? "#f9f9f9" : "#eaeaea",
              borderRadius: "8px",
              marginBottom: "16px",
            }}
          >
            <ListItemAvatar>
              <YoutubeIcon sx={{ color: "#FF0000" }} />
            </ListItemAvatar>
            <ListItemText primary={item.title} secondary={item.description} />
            <Box sx={{ width: '100%', justifyContent: 'center', alignItems: 'center', display: 'flex', flexDirection: 'column' }}>
              <Stepper activeStep={currentStep}>
                {item.steps.map((label, stepIndex) => {
                  const stepProps: { completed?: boolean } = {};

                  if (isStepSkipped(index, stepIndex)) {
                    stepProps.completed = false;
                  }

                  return (
                    <Step key={`step-${index}-${stepIndex}`} {...stepProps}>
                      <StepLabel>{label}</StepLabel>
                    </Step>
                  );
                })}
              </Stepper>

              <Box
                sx={{
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  width: youtubeWidth,
                  height: { sm: '25vw' },
                  marginY: 2,
                }}
              >
                <iframe
                  src={item.src[currentStep % item.src.length]}
                  title="YouTube video player"
                  style={{
                    borderRadius: "8px",
                    width: "100%",
                    height: "100%",
                  }}
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
                {isCompleted ? (
                <React.Fragment>
                  <CustomTypography sx={{ mt: 2, mb: 1 }}>
                    You can find more videos on the {item.channel} Youtube Channel. Thank you.
                  </CustomTypography>
                  <Box sx={{ display: 'flex', flexDirection: 'row', pt: 2 }}>
                    <Box sx={{ flex: '1 1 auto' }} />
                    <Button onClick={() => handleReset(index)}>Reset</Button>
                  </Box>
                </React.Fragment>
              ) : (
                <React.Fragment>
                  <Box sx={{ display: 'flex', flexDirection: 'row', pt: 2 }}>
                    <Button
                      color="inherit"
                      disabled={currentStep === 0}
                      onClick={() => handleBack(index)}
                      sx={{ mr: 1 }}
                    >
                      Back
                    </Button>
                    <Box sx={{ flex: '1 1 auto' }} />
                    {isStepOptional(currentStep) && (
                      <Button
                        color="inherit"
                        onClick={() => handleSkip(index)}
                        sx={{ mr: 1 }}
                      >
                        Skip
                      </Button>
                    )}
                    <Button onClick={() => handleNext(index)}>
                      {currentStep === item.steps.length - 1
                        ? 'Finish'
                        : 'Next'}
                    </Button>
                  </Box>
                </React.Fragment>
              )}
              </Box>
              
              {item.stepsLabels ? (
                <Accordion sx={{ width: '100%' }}>
                  <AccordionSummary
                    expandIcon={<ExpandMoreIcon />}
                    aria-controls="panel1-content"
                  >
                    <CustomTypography component="span">Click for Transcriptions</CustomTypography>
                  </AccordionSummary>
                  <AccordionDetails>
                    {item.stepsLabels[currentStep]}
                  </AccordionDetails>
                </Accordion>
              ) : (
                ''
              )}

              </Box>
              
              </ListItem>
        //   <Tooltip title={`Play: ${item.src}?`} arrow>
        // </Tooltip>
  );     })}
      </List>
      </>
  );
}
